import { adminPool, closeAdminPool } from '../src/tests/test-admin';

/**
 * Script: cleanup-synthetic-data.ts
 * Purpose: Safely identify and remove disposable synthetic demo records
 *          generated by earlier analytics seed runs.
 *
 * Requirements:
 *   - Uses a SINGLE atomic transaction on a single privileged connection.
 *   - Scopes deletion strictly to verified demo records and demo workflows.
 *   - Leaves all genuine workflows, runs, users, and customer data intact.
 *   - Dry-run inspection by default; pass --confirm to execute.
 */

async function main() {
  const isConfirm = process.argv.includes('--confirm');

  console.log(`[cleanup] Mode: ${isConfirm ? 'EXECUTE (ATOMIC TRANSACTION)' : 'DRY-RUN (INSPECTION ONLY)'}`);

  const client = await adminPool.connect();

  try {
    const dummyEmails = [
      'sarah.c@example.com',
      'm.scott@dunder.com',
      'elena.r@example.org',
      'dmiller@company.io',
      'amanda.b@example.net',
      'j.holden@roci.org',
      'naomi.n@belt.com',
      'alex.k@mars.gov',
    ];

    // 1. Audit matching synthetic rows
    const demoWfs = await client.query<{ id: number; name: string }>(`
      SELECT id, name FROM public.workflows
      WHERE organization_id = 1
        AND name IN ('Front Desk Patient Intake Agent', 'After-Hours Emergency Triage Agent');
    `);
    const demoWfIds = demoWfs.rows.map((r) => r.id);

    const runsCount = await client.query<{ count: string }>(`
      SELECT COUNT(*) as count FROM public.workflow_runs
      WHERE name LIKE 'Patient Call #%'
         OR workflow_id = ANY($1::int[]);
    `, [demoWfIds]);

    const apptsCount = await client.query<{ count: string }>(`
      SELECT COUNT(*) as count FROM business_ext.appointments
      WHERE notes = 'Scheduled via AI voice intake'
         OR acuity_workflow_id = ANY($1::int[]);
    `, [demoWfIds]);

    const interactionsCount = await client.query<{ count: string }>(`
      SELECT COUNT(*) as count FROM business_ext.interactions
      WHERE summary = 'Autonomous call successfully resolved';
    `);

    const timelineCount = await client.query<{ count: string }>(`
      SELECT COUNT(*) as count FROM business_ext.contact_timeline_events
      WHERE contact_id IN (
        SELECT id FROM business_ext.contacts WHERE email = ANY($1::text[])
      );
    `, [dummyEmails]);

    const contactsCount = await client.query<{ count: string }>(`
      SELECT COUNT(*) as count FROM business_ext.contacts
      WHERE email = ANY($1::text[]);
    `, [dummyEmails]);

    // Check genuine data to confirm isolation
    const genuineRuns = await client.query<{ count: string }>(`
      SELECT COUNT(*) as count FROM public.workflow_runs
      WHERE NOT (name LIKE 'Patient Call #%' OR workflow_id = ANY($1::int[]));
    `, [demoWfIds]);

    const genuineWfs = await client.query<{ count: string }>(`
      SELECT COUNT(*) as count FROM public.workflows
      WHERE NOT (organization_id = 1 AND name IN ('Front Desk Patient Intake Agent', 'After-Hours Emergency Triage Agent'));
    `);

    console.log('[cleanup] Identified disposable synthetic records:');
    console.log(`  - Demo workflows: ${demoWfs.rows.length} (IDs: ${demoWfIds.join(', ')})`);
    console.log(`  - Demo workflow_runs: ${runsCount.rows[0]?.count || 0}`);
    console.log(`  - Demo appointments: ${apptsCount.rows[0]?.count || 0}`);
    console.log(`  - Demo interactions: ${interactionsCount.rows[0]?.count || 0}`);
    console.log(`  - Demo timeline events: ${timelineCount.rows[0]?.count || 0}`);
    console.log(`  - Demo contacts: ${contactsCount.rows[0]?.count || 0}`);

    console.log('\n[cleanup] Verified genuine records to preserve:');
    console.log(`  - Genuine workflow_runs preserved: ${genuineRuns.rows[0]?.count || 0}`);
    console.log(`  - Genuine workflows preserved: ${genuineWfs.rows[0]?.count || 0}`);

    if (!isConfirm) {
      console.log('\n[cleanup] Dry run complete. No database records modified.');
      console.log('[cleanup] Pass --confirm to execute the single atomic cleanup transaction.');
      return;
    }

    // Execute atomic transaction on single privileged client
    console.log('\n[cleanup] Beginning atomic deletion transaction on single connection...');
    await client.query('BEGIN');

    // 1. Delete dependent appointments
    const delAppts = await client.query(`
      DELETE FROM business_ext.appointments
      WHERE notes = 'Scheduled via AI voice intake'
         OR acuity_workflow_id = ANY($1::int[]);
    `, [demoWfIds]);
    console.log(`  [✓] Deleted ${delAppts.rowCount} appointments`);

    // 2. Delete dependent interactions
    const delInteractions = await client.query(`
      DELETE FROM business_ext.interactions
      WHERE summary = 'Autonomous call successfully resolved';
    `);
    console.log(`  [✓] Deleted ${delInteractions.rowCount} interactions`);

    // 3. Delete dependent contact timeline events
    const delTimeline = await client.query(`
      DELETE FROM business_ext.contact_timeline_events
      WHERE contact_id IN (
        SELECT id FROM business_ext.contacts WHERE email = ANY($1::text[])
      );
    `, [dummyEmails]);
    console.log(`  [✓] Deleted ${delTimeline.rowCount} contact timeline events`);

    // 4. Delete demo contacts
    const delContacts = await client.query(`
      DELETE FROM business_ext.contacts
      WHERE email = ANY($1::text[]);
    `, [dummyEmails]);
    console.log(`  [✓] Deleted ${delContacts.rowCount} contacts`);

    // 5. Delete synthetic workflow runs
    const delRuns = await client.query(`
      DELETE FROM public.workflow_runs
      WHERE name LIKE 'Patient Call #%'
         OR workflow_id = ANY($1::int[]);
    `, [demoWfIds]);
    console.log(`  [✓] Deleted ${delRuns.rowCount} workflow_runs`);

    // 6. Delete demo workflows
    const delWfs = await client.query(`
      DELETE FROM public.workflows
      WHERE id = ANY($1::int[]);
    `, [demoWfIds]);
    console.log(`  [✓] Deleted ${delWfs.rowCount} demo workflows`);

    // Commit single atomic transaction
    await client.query('COMMIT');
    console.log('\n[cleanup] Single atomic cleanup transaction committed successfully!');

    // Post-verification
    const postRuns = await client.query<{ count: string }>('SELECT COUNT(*) as count FROM public.workflow_runs;');
    const postWfs = await client.query<{ count: string }>('SELECT COUNT(*) as count FROM public.workflows;');
    console.log(`[cleanup] Post-cleanup remaining workflow_runs: ${postRuns.rows[0]?.count}`);
    console.log(`[cleanup] Post-cleanup remaining workflows: ${postWfs.rows[0]?.count}`);
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('[cleanup] Transaction aborted and rolled back due to error:', error);
    throw error;
  } finally {
    client.release();
    await closeAdminPool();
  }
}

main().catch((err) => {
  console.error('[cleanup] Fatal error:', err);
  process.exit(1);
});
